const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], state={candidates:[],selected:null,compare:new Set(),table:true,started:Date.now(),session:crypto.randomUUID()};
const esc=s=>String(s??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
async function api(path,options={}){const r=await fetch(path,{headers:{"content-type":"application/json",...(options.headers||{})},...options});let d;try{d=await r.json()}catch{d={error:`Request failed (${r.status}).`}}if(!r.ok)throw Error(d.error||`Request failed (${r.status}).`);return d}
async function route(){const name=location.hash==="#dashboard"||new URLSearchParams(location.search).get('view')==='dashboard'?'dashboard':'intake';$$('.view').forEach(v=>v.classList.toggle('hidden',v.id!==name));$$('[data-route]').forEach(a=>a.setAttribute('aria-current',a.dataset.route===name?'page':'false'));if(name==='dashboard'){const panel=$('#dashboard'),notice=$('#recruiter-access');panel.dataset.authorized='false';notice.textContent='Checking recruiter access…';$('#login-form').classList.add('hidden');$('#setup-form').classList.add('hidden');try{const result=await api('/api/recruiter-session');notice.textContent='';if(result.authorized){panel.dataset.authorized='true';$('#setup-form').classList.toggle('hidden',!result.setupRequired);await loadCandidates()}else{$('#login-form').classList.remove('hidden');$('#setup-link').classList.toggle('hidden',!result.setupAvailable)}}catch(e){notice.textContent='Could not verify recruiter access. Try refreshing.'}}}
addEventListener('hashchange',route);route();
$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,error=$('#login-error'),button=form.querySelector('button');error.textContent='';button.disabled=true;try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();await route()}catch(e){error.textContent=e.message}finally{button.disabled=false}});
$('#setup-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,error=$('#setup-error'),button=form.querySelector('button'),data=Object.fromEntries(new FormData(form));error.textContent='';if(data.password!==data.confirmPassword){error.textContent='Passwords do not match.';return}button.disabled=true;try{await api('/api/auth/setup',{method:'POST',body:JSON.stringify({password:data.password})});form.reset();await route()}catch(e){error.textContent=e.message}finally{button.disabled=false}});
$('#signout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'});state.candidates=[];state.selected=null;await route()}catch(e){$('#recruiter-access').textContent=e.message}};
$('#intake-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,err=$('#form-error');err.textContent='';if(!f.reportValidity()){err.textContent='Complete the required fields above.';return}const data=Object.fromEntries(new FormData(f));const file=$('#resume').files[0];const button=f.querySelector('button[type=submit]');button.disabled=true;button.textContent='SUBMITTING…';try{let resume=null,resumeText='';if(file){if(file.size>5e6)throw Error('Resume must be 5 MB or smaller.');if(!/\.(pdf|txt)$/i.test(file.name))throw Error('Upload a PDF or plain-text resume.');resumeText=await extractResumeText(file);resume={name:file.name,type:file.type||(/\.pdf$/i.test(file.name)?'application/pdf':'text/plain'),base64:await toBase64(file)}}const payload={...data,technicalInterests:split(data.technicalInterests),preferredLocations:split(data.preferredLocations),relevantSkills:split(data.relevantSkills),resume,resumeText,sessionId:state.session,durationMs:Date.now()-state.started};const r=await api('/api/candidates',{method:'POST',body:JSON.stringify(payload)});$('#code').textContent=r.confirmationCode;f.classList.add('hidden');$('#confirmation').classList.remove('hidden');$('#confirmation').focus()}catch(x){err.textContent=x.message;err.focus()}finally{button.disabled=false;button.textContent='SUBMIT CHECK-IN'}});
$('#another').onclick=()=>{$('#intake-form').reset();$('#intake-form').classList.remove('hidden');$('#confirmation').classList.add('hidden');state.started=Date.now();$('#intake-form input').focus()};
const split=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean),toBase64=file=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]);r.onerror=no;r.readAsDataURL(file)});
async function extractResumeText(file){if(/\.txt$/i.test(file.name))return(await file.text()).slice(0,20000);const pdfjs=await import('/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc='/pdf.worker.mjs';const document=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;let text='';try{for(let i=1;i<=Math.min(document.numPages,30)&&text.length<20000;i++){const page=await document.getPage(i),content=await page.getTextContent();text+=content.items.map(item=>item.str||'').join(' ')+'\n'}}finally{await document.destroy()}if(!text.trim())throw Error('This PDF has no selectable text. Please upload a text-based PDF or a .txt resume.');return text.slice(0,20000)}
async function loadCandidates(){const p=new URLSearchParams({q:$('#search').value,status:$('#status').value,event:$('#event-filter').value});$('#sync').textContent='Refreshing…';try{const r=await api(`/api/candidates?${p}`);state.candidates=r.candidates;renderList();$('#sync').textContent=`Updated ${new Date().toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}`;if(state.selected){const fresh=state.candidates.find(c=>c.id===state.selected.id);if(fresh){state.selected=fresh;renderDetail(fresh)}}}catch(e){$('#sync').textContent=e.message}}
let timer;[$('#search'),$('#status'),$('#event-filter')].forEach(x=>x.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(loadCandidates,250)}));$('#refresh').onclick=loadCandidates;
function renderList(){$('#count').textContent=state.candidates.length;const root=$('#candidate-list');root.innerHTML=state.candidates.length?state.candidates.map(c=>`<article class="candidate-card" data-status="${esc(c.recordStatus)}"><input type="checkbox" aria-label="Compare ${esc(c.firstName)} ${esc(c.lastName)}" data-compare="${c.id}" ${state.compare.has(c.id)?'checked':''}><button class="open" data-open="${c.id}"><h3>${esc(c.preferredName||c.firstName)} ${esc(c.lastName)}</h3><p>${esc(c.desiredFunction)} · ${esc(c.university)}</p><div class="chips">${c.relevantSkills.slice(0,4).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><p><span class="badge">${esc(c.recordStatus)}</span> <span class="badge ${c.approvalStatus==='Approved'?'approved':''}">${esc(c.approvalStatus)} summary</span></p></button><select data-status-id="${c.id}" aria-label="Status for ${esc(c.firstName)} ${esc(c.lastName)}">${['New','Reviewed','Follow-Up','Interview Requested','Closed'].map(s=>`<option ${s===c.recordStatus?'selected':''}>${s}</option>`).join('')}</select></article>`).join(''):'<div class="panel empty"><h2>No candidates found</h2><p>Change the filters or submit a synthetic candidate check-in.</p></div>';$$('[data-open]').forEach(b=>b.onclick=()=>{state.selected=state.candidates.find(c=>c.id===b.dataset.open);renderDetail(state.selected)});$$('[data-compare]').forEach(x=>x.onchange=()=>{x.checked?state.compare.add(x.dataset.compare):state.compare.delete(x.dataset.compare);syncCompare()});$$('[data-status-id]').forEach(s=>s.onchange=async()=>{await api(`/api/candidates/${s.dataset.statusId}`,{method:'PATCH',body:JSON.stringify({recordStatus:s.value})});loadCandidates()});syncCompare()}
function syncCompare(){$('#compare-count').textContent=state.compare.size;$('#compare-btn').disabled=state.compare.size<2||state.compare.size>4;renderTable()}
function renderTable(){const root=$('#sheet-view');if(!root)return;const columns=[['Candidate',c=>`${c.preferredName||c.firstName} ${c.lastName}`],['Email',c=>c.email],['University',c=>c.university],['Major',c=>c.major],['Graduation',c=>c.graduationDate],['Desired function',c=>c.desiredFunction],['Skills',c=>c.relevantSkills.join(', ')],['Event',c=>c.eventCode],['Status',c=>c.recordStatus],['AI consent',c=>c.aiConsent?'Yes':'No'],['Approval',c=>c.approvalStatus],['Recruiter notes',c=>c.observations?.conversationNotes||''],['Interview questions',c=>(c.summary?.interviewQuestions||[]).map(x=>x.text).join(' | ')]];root.innerHTML=state.candidates.length?`<table><thead><tr><th scope="col">Open</th>${columns.map(([label])=>`<th scope="col">${esc(label)}</th>`).join('')}</tr></thead><tbody>${state.candidates.map(c=>`<tr><td><button class="sheet-open" data-sheet-open="${esc(c.id)}">DETAILS</button></td>${columns.map(([,read])=>`<td>${esc(read(c))}</td>`).join('')}</tr>`).join('')}</tbody></table>`:'<p class="empty">No candidates match these filters.</p>';$$('[data-sheet-open]').forEach(button=>button.onclick=()=>{state.selected=state.candidates.find(c=>c.id===button.dataset.sheetOpen);renderDetail(state.selected);$('#detail').scrollIntoView({block:'nearest'})})}
$('#table-toggle').onclick=()=>{state.table=!state.table;$('#dashboard').dataset.view=state.table?'table':'cards';$('#table-toggle').textContent=state.table?'CARD VIEW':'TABLE VIEW'};$('#dashboard').dataset.view='table';
document.addEventListener('click',event=>{if(event.target.closest('[data-open],[data-sheet-open]'))$('#delete-record').disabled=false});
$('#delete-record').onclick=async()=>{if(!state.selected)return;const name=`${state.selected.firstName} ${state.selected.lastName}`;if(!confirm(`Permanently delete ${name}'s record and uploaded resume? This cannot be undone.`))return;const button=$('#delete-record');button.disabled=true;try{await api(`/api/candidates/${state.selected.id}`,{method:'DELETE'});state.compare.delete(state.selected.id);state.selected=null;$('#detail').innerHTML='<div class="empty"><h2>Record deleted</h2><p>The candidate record and uploaded resume were removed.</p></div>';await loadCandidates()}catch(e){alert(e.message);button.disabled=false}};
function facts(c){return [['University',c.university],['Degree',c.degreeProgram],['Major',c.major],['Graduation',c.graduationDate],['GPA',c.gpa||'Not supplied'],['Work authorization',c.workAuthorization||'Not supplied'],['Preferred locations',c.preferredLocations.join(', ')||'Not supplied'],['Coursework',c.relevantCoursework||'Not supplied']].map(([k,v])=>`<div class="fact"><small>${k}</small>${esc(v)}</div>`).join('')}
function renderDetail(c){const o=c.observations||{},summary=c.summary;$('#detail').innerHTML=`<p class="eyebrow">CANDIDATE RECORD</p><h2>${esc(c.preferredName||c.firstName)} ${esc(c.lastName)}</h2><p>${esc(c.email)}${c.phone?` · ${esc(c.phone)}`:''}</p><div class="facts">${facts(c)}</div><div class="detail-section"><h3>Career evidence</h3><p><strong>Desired function:</strong> ${esc(c.desiredFunction)}</p><p><strong>Technical interests:</strong> ${esc(c.technicalInterests.join(', ')||'Not supplied')}</p><p><strong>Skills:</strong> ${esc(c.relevantSkills.join(', ')||'Not supplied')}</p><p><strong>Projects:</strong> ${esc(c.projectExperience||'Not supplied')}</p><p><strong>Resume:</strong> ${esc(c.resumeName||'Not supplied')}</p></div><div class="detail-section"><h3>Recruiter capture</h3>${field('Recruiter name','recruiterName',o.recruiterName,1)}${field('Conversation notes','conversationNotes',o.conversationNotes)}${field('Areas of interest discussed','areasDiscussed',o.areasDiscussed)}${field('Follow-up questions','followUpQuestions',o.followUpQuestions)}${field('Recommended next steps','recommendedNextSteps',o.recommendedNextSteps)}${field('Candidate questions','candidateQuestions',o.candidateQuestions)}<button id="save-notes" class="secondary">SAVE RECRUITER NOTES</button></div><div class="detail-section"><h3>AI-assisted draft</h3><p class="hint">Generated only from candidate profile, resume text, and recruiter notes. Requires recruiter verification.</p><div id="summary-error" class="alert" role="alert"></div>${summaryView(summary)}<div class="actions"><button id="generate" class="primary">${summary?'REGENERATE DRAFT':'GENERATE GROUNDED DRAFT'}</button>${summary?'<button id="approve" class="secondary">APPROVE EDITED DRAFT</button><button id="reject" class="secondary">REJECT DRAFT</button>':''}</div>${c.approvalTimestamp?`<p class="hint">${esc(c.approvalStatus)} by ${esc(c.approvedBy)} on ${new Date(c.approvalTimestamp).toLocaleString()}</p>`:''}</div>`;$('#save-notes').onclick=saveNotes;$('#generate').onclick=generateSummary;if(summary){$('#approve').onclick=()=>reviewSummary('Approved');$('#reject').onclick=()=>reviewSummary('Rejected')}}
const field=(label,name,value,rows=3)=>`<label>${label}${rows===1?`<input data-note="${name}" value="${esc(value)}">`:`<textarea data-note="${name}" rows="${rows}">${esc(value)}</textarea>`}</label>`;
function summaryView(s){if(!s)return '<div class="empty"><p>No draft generated.</p></div>';return `<p><span class="badge ${state.selected.approvalStatus==='Approved'?'approved':''}">${esc(state.selected.approvalStatus)}</span></p>${s.statements.map((x,i)=>`<div class="summary-item"><label>Statement ${i+1}<textarea data-statement="${i}">${esc(x.text)}</textarea></label><p>${x.citations.map(c=>`<span class="citation">[${esc(c)}]</span>`).join(' ')}</p></div>`).join('')}<h4>Interview questions</h4><p class="hint">Review and edit before using these questions in an interview.</p>${(s.interviewQuestions||[]).map((x,i)=>`<div class="summary-item"><label>Question ${i+1}<textarea data-question="${i}">${esc(x.text)}</textarea></label><p>${x.citations.map(c=>`<span class="citation">[${esc(c)}]</span>`).join(' ')}</p></div>`).join('')||'<p>None generated.</p>'}<h4>Missing information</h4><ul>${s.missingInformation.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>None flagged.</li>'}</ul>`}
async function saveNotes(refresh=true){const observations={};$$('[data-note]').forEach(x=>observations[x.dataset.note]=x.value);try{const r=await api(`/api/candidates/${state.selected.id}`,{method:'PATCH',body:JSON.stringify({observations})});state.selected=r.candidate;if(refresh){renderDetail(state.selected);loadCandidates()}return r.candidate}catch(e){$('#summary-error').textContent=e.message;throw e}}
async function generateSummary(){const b=$('#generate');$('#summary-error').textContent='';b.disabled=true;b.textContent='GENERATING…';try{await saveNotes(false);await api(`/api/candidates/${state.selected.id}/summary`,{method:'POST',body:'{}'});const r=await api(`/api/candidates/${state.selected.id}`);state.selected=r.candidate;renderDetail(state.selected)}catch(e){const err=$('#summary-error'),button=$('#generate');err.textContent=e.message;button.disabled=false;button.textContent='GENERATE GROUNDED DRAFT'}}
async function reviewSummary(action){const editedStatements=state.selected.summary.statements.map((s,i)=>({text:$(`[data-statement="${i}"]`).value,citations:s.citations}));const editedQuestions=(state.selected.summary.interviewQuestions||[]).map((s,i)=>({text:$(`[data-question="${i}"]`).value,citations:s.citations}));try{const r=await api(`/api/candidates/${state.selected.id}/review`,{method:'POST',body:JSON.stringify({action,editedStatements,editedQuestions})});state.selected=r.candidate;renderDetail(state.selected);loadCandidates()}catch(e){$('#summary-error').textContent=e.message}}
$('#compare-btn').onclick=()=>{const cs=state.candidates.filter(c=>state.compare.has(c.id));$('#comparison').innerHTML=cs.map(c=>`<article class="compare-card"><h3>${esc(c.preferredName||c.firstName)} ${esc(c.lastName)}</h3><p>${esc(c.university)} · ${esc(c.major)}</p><p><span class="badge">${esc(c.recordStatus)}</span></p><h4>Desired function</h4><p>${esc(c.desiredFunction)}</p><h4>Skills</h4><p>${esc(c.relevantSkills.join(', ')||'Not supplied')}</p><h4>Project experience</h4><p>${esc(c.projectExperience||'Not supplied')}</p><h4>Verified snapshot</h4>${c.approvalStatus==='Approved'&&c.summary?c.summary.statements.map(s=>`<p>${esc(s.text)} ${s.citations.map(x=>`<span class="citation">[${esc(x)}]</span>`).join(' ')}</p>`).join(''):'<p>Not approved.</p>'}</article>`).join('');$('#compare-dialog').showModal()};$('[data-close]').onclick=()=>$('#compare-dialog').close();
setInterval(()=>{if(location.hash==='#dashboard')loadCandidates()},10000);
